ee:message.ee:set-payload:
%dw 2.0
output text/xml
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns urn urn:enterprise.soap.sforce.com
---
{
	soapenv#Envelope: {
		soapenv#Header: {
			urn#LoginScopeHeader: {
				urn#organizationId: '',
				urn#portalId: ''  
			}
		},	
		soapenv#Body: 
		{
			urn#login: {
				urn#username: vars.credentialsToken.username,
				urn#password: vars.credentialsToken.password  
			}	    
		}		
	}
}
